// spdRedSkins.js — S.P.D. Red Ranger's 10 alt skins (cosmetic only). The sheets are generated by
// tools/spd_red_build/gen_spd_red_skins.py as `<sheet>__<tag>.png` (an exact palette map of the red suit ramp and the
// white trim ramp; outlines, the visor, the poster and the blue gem are untouched). This module REGISTERS the skins
// into skins.js SKINS.spd_red at load (so the shared skins.js table is untouched) and gives the render layer the
// per-skin accent colour for code-drawn FX (sparks, intro streak, blink smear). Nothing here is read by the simulation.
import { SKINS } from './skins.js'
import { spdRed as SPD_RED_CHAR } from './spdRedData.js'

// tag → display name. `spdRedAlienX` keeps the engine's generic Alien X starfield overlay (skin id ends "AlienX").
// S.P.D. Blue and Omega are NOT skins: both are their own fighters.
export const SPD_RED_SKIN_LIST = [
  ['green', 'S.P.D. Green (Bridge)'], ['yellow', 'S.P.D. Yellow (Z)'], ['pink', 'S.P.D. Pink (Syd)'],
  ['shadow', 'Shadow Ranger (Doggie Cruger)'], ['swat', 'S.W.A.T. Mode'], ['battlizer', 'Red Battlizer'],
  ['asquad', 'A-Squad (Rogue)'], ['ben10', 'Ben 10'], ['albedo', 'Albedo'], ['alienx', 'Alien X'],
]
export const spdRedSkinId = tag => tag === 'alienx' ? 'spdRedAlienX' : `spd_red_${tag}`
export const spdRedRetag = (sheet, tag) => (tag && sheet ? sheet.replace(/\.png$/i, `__${tag}.png`) : sheet)

const _sets = new Map()
export function spdRedSkinSet(set, tag) {
  if (!tag || !set) return set
  let byTag = _sets.get(set); if (!byTag) _sets.set(set, byTag = {})
  return byTag[tag] || (byTag[tag] = Object.fromEntries(Object.entries(set).map(([k, a]) => [k, a?.sheet ? { ...a, sheet: spdRedRetag(a.sheet, tag) } : a])))
}

// Code-drawn accent per skin ([r, g, b]): hit sparks, the intro streak, the blink smear. Default = S.P.D. red.
const ACCENT = {
  _: [255, 60, 40], green: [70, 235, 70], yellow: [255, 220, 40], pink: [255, 120, 195], shadow: [90, 120, 255],
  swat: [220, 30, 40], battlizer: [255, 200, 60], asquad: [255, 44, 32], albedo: [255, 40, 30], ben10: [120, 255, 80], alienx: [235, 240, 255],
}
export const spdRedAccent = (f, a = 1) => { const c = ACCENT[f?._recolorTag] || ACCENT._; return `rgba(${c[0]},${c[1]},${c[2]},${a})` }

// Register into SKINS.spd_red (idempotent).
const list = SKINS.spd_red || (SKINS.spd_red = [{ id: 'default', name: 'Default', unlockLevel: 0, portrait: SPD_RED_CHAR.portrait, spriteScale: SPD_RED_CHAR.spriteScale, animationData: null }])
for (const [tag, name] of SPD_RED_SKIN_LIST) {
  const id = spdRedSkinId(tag)
  if (list.some(s => s.id === id)) continue
  list.push({ id, name, unlockLevel: 0, portrait: spdRedRetag(SPD_RED_CHAR.portrait, tag), spriteScale: SPD_RED_CHAR.spriteScale,
    animationData: spdRedSkinSet(SPD_RED_CHAR.animationData, tag), recolorTag: tag })
}
